mapper.select:
WITH voucher AS ( SELECT TEMP.happenDate, /**发生日期**/ TEMP.booksetDate, /**账套日期**/ TEMP.bookDate, /**入账日期**/ TEMP.bookId, /**凭证编号**/ TEMP.booksetId /**账套代码**/ FROM ( SELECT cur.HAPPEN_DATE as happenDate, /**发生日期**/ cur.BOOKSET_DATE as booksetDate, /**账套日期**/ cur.BOOK_DATE as bookDate,/**入账日期**/ cur.BOOK_ID as bookId,/**凭证编号**/ cur.BOOKSET_ID as booksetId, /**账套代码**/ cur.OFFSET_FLAG as offsetFlag, /**冲正标识**/ ROW_NUMBER() OVER(PARTITION BY cur.BOOKSET_ID, cur.BOOK_ID ORDER BY cur.BOOK_ORDER desc) as rn FROM BOK_BOOKDETAIL_CURRENT cur WHERE 1=1 AND cur.BOOKSET_ID = #{booksetId} /**账套代码**/ AND cur.BOOK_DATE <= #{bookDate} /**入账日**/ AND cur.TABLE_ID = #{tableId} /**场景代码**/ AND cur.TRADE_ID = #{tradeId} /**交易编号**/ AND cur.HAPPEN_DATE = #{happenDate} /**发生日**/
AND cur.HAPPEN_DATE >= #{beginHappenCycDate}
AND cur.HAPPEN_DATE <= #{endHappenCycDate}
) TEMP WHERE TEMP.rn = 1 AND TEMP.offsetFlag = #{offsetFlag} /**冲正标识**/ )
SELECT crt.*,/**账务明细表（当前表）.全部项目**/ book.BOOKSET_DATE booksetDateNew /**账套日期表.账套日期**/ FROM BOK_BOOKDETAIL_CURRENT crt INNER JOIN voucher vr on crt.happen_date = vr.happenDate and crt.BOOKSET_DATE = vr.booksetDate and crt.BOOK_DATE = vr.bookDate and crt.BOOK_ID = vr.bookId and crt.bookset_id = vr.booksetId INNER JOIN BOK_BOOKSET_DATE book ON book.BOOKSET_ID = crt.BOOKSET_ID WHERE 1 =1
/**科目性质**/ AND crt.BASE_SUBJECT_NATURE IN
#{baseSubjectNature}
AND crt.BOK_DETAIL_ID = #{bokDetailId} /**账务明细代码**/
AND ( crt.HAPPEN_DATE <= #{onwayDate} AND crt.ONWAY_DATE > #{onwayDate})
ORDER BY crt.HAPPEN_DATE ASC

SELECT D.BOOKSET_ID, D.BOK_DETAIL_ID FROM FIN_PRODUCT A INNER JOIN FIN_PRODUCT_ADD C ON A.FINPROD_ID = C.FINPROD_ID INNER JOIN BOK_BOOKSET B ON C.PORTFOLIO_ID = B.ACCT_SUBJECT_ID INNER JOIN BOK_DETAIL_ID D ON D.BOOKSET_ID = B.BOOKSET_ID AND D.BUSI_ID = A.FINPROD_ID WHERE A.FINPROD_ID = #{finProdId} AND A.PROFIT_TYPE = #{expectedReturnType}
UNION ALL
SELECT B.BOOKSET_ID, D.BOK_DETAIL_ID FROM FIN_PRODUCT A INNER JOIN BOK_BOOKSET B ON A.FINPROD_ID = B.ACCT_SUBJECT_ID INNER JOIN BOK_DETAIL_ID D ON D.BOOKSET_ID = B.BOOKSET_ID AND D.BUSI_ID = A.FINPROD_ID WHERE A.FINPROD_ID = #{finProdId} AND A.PROFIT_TYPE != #{expectedReturnType}

SELECT T1.FINPROD_ID AS subcombinedCode, SUM(CASE WHEN T1.PS = #{tradeDirectionSubscribe} THEN T1.TRADE_AMT WHEN T1.PS = #{tradeDirectionRedemption} THEN -1 * T1.TRADE_AMT END) AS transactionAmount FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 INNER JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID AND T2.PA_BUSS_TYPE IN (#{productTradingCapitalAllocation},#{productCapitalAdjustment}) WHERE T1.TRADE_STATUS = #{transactionStatusInitial} AND T1.TRADE_DATE >= to_date(#{startDate},'yyyy-MM-dd') AND to_date(#{endDate},'yyyy-MM-dd') >= T1.TRADE_DATE AND (T1.FINPROD_ID IN
null) or T1.FINPROD_ID in (
#{code}
) GROUP BY T1.FINPROD_ID

SELECT tpda.PORTFOLIO_ID AS subcombinedCode, SUM(case when tpd.PS = '${tradeDirectionSubscribe}' then tpd.TRADE_AMT when tpd.PS = '${tradeDirectionRedemption}' then -1*tpd.TRADE_AMT end) AS transactionAmount FROM TRD_PRODUCT_DEAL tpd INNER JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpd.TRADE_ID = tpda.TRADE_ID INNER JOIN PA_TRD_PRODUCT_DEAL ptpd ON ptpd.TRADE_ID = tpd.TRADE_ID AND ptpd.PA_BUSS_TYPE IN (#{productTradingCapitalAllocation},#{productCapitalAdjustment}) WHERE tpd.TRADE_STATUS <> #{transactionStatusInitial} AND tpd.IS_CANCEL = #{yes_no} AND to_char(tpd.TRADE_DATE,'yyyy-MM-dd') <= #{endDate} AND (tpda.PORTFOLIO_ID in
null) or tpda.PORTFOLIO_ID in (
#{code}
) GROUP BY tpda.PORTFOLIO_ID
